#!/usr/bin/env bash
set -euo pipefail
ROOT="${1:-$PWD}"
PORT="${PORT:-8765}"
cd "$ROOT"
STAMP="$(date +%Y%m%d_%H%M%S)"
BACKUP=".mikrobot_backup_$STAMP"
mkdir -p "$BACKUP/static" "$BACKUP/tests"
for f in app.py start.sh requirements.txt index.html knowledge.json .env.example; do [ -f "$f" ] && cp -a "$f" "$BACKUP/" || true; done
[ -d static ] && cp -a static "$BACKUP/" || true
[ -d tests ] && cp -a tests "$BACKUP/" || true
echo "Backup criado em $BACKUP"
printf %s "" | base64 -d > "app.py"
printf %s "ZmFzdGFwaT49MC4xMTYsPDEKdXZpY29ybltzdGFuZGFyZF0+PTAuMzUsPDEKaHR0cHg+PTAuMjgsPDEKcHN1dGlsPj03LDw4CnB5ZGFudGljPj0yLjExLDwzCnB5dGVzdD49OCw8OQo=" | base64 -d > "requirements.txt"
printf %s "IyEvdXNyL2Jpbi9lbnYgYmFzaApzZXQgLWV1byBwaXBlZmFpbApjZCAiJChkaXJuYW1lICIkMCIpIgpweXRob24zIC1tIHBpcCBpbnN0YWxsIC1xIC1yIHJlcXVpcmVtZW50cy50eHQKZXhlYyBweXRob24zIC1tIHV2aWNvcm4gYXBwOmFwcCAtLWhvc3QgMC4wLjAuMCAtLXBvcnQgIiR7UE9SVDotODc2NX0iIC0td29ya2VycyAxCg==" | base64 -d > "start.sh"
mkdir -p "static"
printf %s "" | base64 -d > "static/index.html"
printf %s "" | base64 -d > "knowledge.json"
printf %s "T1BFTkFJX0FQSV9LRVk9Ck9QRU5BSV9NT0RFTD1ncHQtNS42LWx1bmEKT1BFTkFJX0JBU0U9aHR0cHM6Ly9hcGkub3BlbmFpLmNvbS92MQpQT1JUPTg3NjUKV0hBVFNBUFBfVE9LRU49CldIQVRTQVBQX1BIT05FX05VTUJFUl9JRD0KV0hBVFNBUFBfQVBJX1ZFUlNJT049CldIQVRTQVBQX1ZFUklGWV9UT0tFTj0K" | base64 -d > ".env.example"
printf %s "" | base64 -d > "README.md"
mkdir -p "tests"
printf %s "" | base64 -d > "tests/test_app.py"
chmod +x start.sh
python3 -m pip install -q -r requirements.txt
python3 -m py_compile app.py
python3 -m pytest -q
pkill -f "uvicorn.*--port $PORT" 2>/dev/null || true
fuser -k "$PORT/tcp" 2>/dev/null || true
sleep 1
nohup env PORT="$PORT" python3 -m uvicorn app:app --host 0.0.0.0 --port "$PORT" --workers 1 > mikrobot.log 2>&1 &
sleep 3
echo "=== HEALTH ==="
curl -fsS "http://127.0.0.1:$PORT/api/health"
echo
echo "=== MIKROBOT JARVIS PRO V2 ONLINE ==="
echo "Porta: $PORT"
